import { z } from 'zod';

import { sellerProductIdParamsSchema } from '../../management/schemas/product.schema.js';

/**
 * Validates multipart metadata for a product image.
 * Cloudinary identifiers and URLs are generated by the server.
 */
export const addProductImageSchema = z
  .object({
    altText: z.string().trim().min(1).max(250).optional(),
  })
  .strict();

export type AddProductImageRequest = z.infer<typeof addProductImageSchema>;

const objectIdSchema = z.string().regex(/^[0-9a-fA-F]{24}$/, 'Must be a valid MongoDB ObjectId.');

/** Validates the product and image IDs used by seller image routes. */
export const productImageParamsSchema = sellerProductIdParamsSchema
  .extend({
    imageId: objectIdSchema,
  })
  .strict();

export type ProductImageParams = z.infer<typeof productImageParamsSchema>;

/** Validates editable metadata for a product image. */
export const updateProductImageSchema = z
  .object({
    altText: z.string().trim().min(1).max(250).optional(),
    isPrimary: z.boolean().optional(),
  })
  .strict()
  .refine((changes) => Object.keys(changes).length > 0, {
    message: 'Provide alt text or a primary-image setting to update.',
  });

export type UpdateProductImageRequest = z.infer<typeof updateProductImageSchema>;

/** Validates the requested order of a product's image IDs. */
export const reorderProductImagesSchema = z
  .object({
    imageIds: z.array(objectIdSchema).min(1),
  })
  .strict()
  .refine(
    ({ imageIds }) =>
      new Set(imageIds.map((imageId) => imageId.toLowerCase())).size === imageIds.length,
    {
      message: 'Each image ID can appear only once.',
      path: ['imageIds'],
    },
  );

export type ReorderProductImagesRequest = z.infer<typeof reorderProductImagesSchema>;
